    "format": "openapi-3.1",
    "title": "TrailPing \u2014 a backcountry GPS tracker fleet telemetry platform for outdoor-gear OEMs API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the TrailPing \u2014 a backcountry GPS tracker fleet telemetry platform for outdoor-gear OEMs API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "TrailPing \u2014 a backcountry GPS tracker fleet telemetry platform for outdoor-gear OEMs API",
        "version": "1.0.0",
        "description": "REST API serving device check-ins (location pings) from a fleet of GPS trackers; OEM partners pull telemetry, audit device fleets, and reconcile ping counts for billing."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc"
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/checkins": {
          "get": {
            "summary": "Cursor-paginated check-in feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/pings": {
          "get": {
            "summary": "Offset/limit ping feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/audit-events": {
          "get": {
            "summary": "Link-header (RFC5988) audit feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/stats/summary": {
          "get": {
            "summary": "Grand reconciliation totals",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/events": {
          "get": {
            "summary": "DEPRECATED legacy feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-30T04:51:42.569588+00:00"
}

